// Remove android.permission.INTERNET from the generated Android manifest.
//
// This app declares operations: [] (see blueprint.edn / scripts/build.mjs) and
// CSP connect-src ipc: only — nothing leaves the device — so the manifest
// must not request (or inherit from a library) INTERNET. The Gradle merger
// directive <uses-permission ... tools:node="remove"/> drops the permission
// from the merged manifest, including any copy merged from a library
// (same mechanism as tabi-mikake, AWAI-3302).
//
// Why a script here: the manifest lives under src-tauri/gen/ (generated by
// `tauri android init` from embedded CLI templates; AndroidConfig has no
// permissions field), so a one-off edit would resurrect on the next init.
// This script is tracked and re-applied after every init by
// scripts/android-apk.sh, which makes the removal persistent.
//
// Usage: node scripts/remove-network-permission.mjs [manifestPath]
// Idempotent: a manifest already carrying tools:node="remove" is left as-is.
import { readFile, writeFile } from "node:fs/promises";
import { existsSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const appDir = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const manifestPath =
  process.argv[2] ??
  resolve(appDir, "src-tauri/gen/android/app/src/main/AndroidManifest.xml");

if (!existsSync(manifestPath)) {
  console.error(`manifest not found: ${manifestPath} (run tauri android init first)`);
  process.exit(1);
}

let xml = await readFile(manifestPath, "utf8");

if (xml.includes('android:name="android.permission.INTERNET" tools:node="remove"')) {
  console.log("already removed: INTERNET carries tools:node=\"remove\"");
  process.exit(0);
}

const plain = /<uses-permission android:name="android\.permission\.INTERNET" \/>/;
if (!plain.test(xml)) {
  console.error("pattern <uses-permission android:name=\"android.permission.INTERNET\" /> not found — refusing to guess");
  process.exit(1);
}

xml = xml.replace(plain, '<uses-permission android:name="android.permission.INTERNET" tools:node="remove" />');

if (!xml.includes("xmlns:tools=")) {
  const open = xml.match(/<manifest[^>]*>/);
  if (!open) {
    console.error("no <manifest> tag found — refusing to guess");
    process.exit(1);
  }
  xml = xml.replace(open[0], open[0].replace(/>$/, ' xmlns:tools="http://schemas.android.com/tools">'));
}

await writeFile(manifestPath, xml);
console.log("removed INTERNET from generated manifest (tools:node=\"remove\")");
